#!/usr/bin/env node

/**
 * Generate `docs/comparison.md` — the published comparison / benchmark page
 * (issue #499, REQ-002).
 *
 * The page must never carry hand-edited figures, so the whole file is
 * generated from committed, independently regenerable inputs:
 *
 *   - `docs/bundle-sizes.md`            (generated by `npm run report:bundle-sizes`)
 *   - `docs/protocol-capability-matrix.md` (Honua's protocol lanes)
 *   - `docs/data/time-to-first-map.json`   (written by `npm run bench:ttfm -- --write-reference`)
 *   - `node_modules/maplibre-gl`           (engine size measured locally from the pinned dependency)
 *
 * External (competitor) figures are cited claims, each with a pinned source
 * URL and an as-of date, curated in the CITATIONS block below — never inline
 * in the markdown.
 *
 * Modes:
 *   - `npm run docs:comparison`        (write): regenerate docs/comparison.md
 *   - `npm run docs:comparison:check`  (check): fail when the committed page
 *     differs from what the inputs produce (freshness gate).
 */

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { gzipSync } from "node:zlib";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const OUTPUT_FILE = path.join(ROOT, "docs", "comparison.md");
const BUNDLE_SIZES_FILE = path.join(ROOT, "docs", "bundle-sizes.md");
const CAPABILITY_MATRIX_FILE = path.join(ROOT, "docs", "protocol-capability-matrix.md");
const TTFM_REFERENCE_FILE = path.join(ROOT, "docs", "data", "time-to-first-map.json");

// ---------------------------------------------------------------------------
// Cited external figures. Every number here must carry a pinned source URL and
// an as-of date. Be conservative and honest: when a range is published, quote
// the range; when the comparison is not apples-to-apples, say so in prose.
// ---------------------------------------------------------------------------
const CITATIONS = {
  arcgisCore: {
    label: "`@arcgis/core` 4.30 (ArcGIS Maps SDK for JavaScript)",
    mainBundleMin: "1.31–1.49 MB",
    mainBundleGzip: "0.36–0.42 MB",
    totalJsTransferred: "3.5–4.1 MB",
    buildOutput: "8.3–10 MB across ~300–740 files",
    asOf: "2024-06-27 (4.30, the last core-sample metrics Esri published in jsapi-resources)",
    retrieved: "2026-07-13",
    source:
      "https://github.com/Esri/jsapi-resources/blob/9fe7d8cc709c5daf3a342e921e897d459955b347/core-samples/.metrics/4.30.0.csv",
    note:
      "Esri's own automated build metrics for its minimal `@arcgis/core` map samples (esbuild, Angular, React, Vue, Rollup, Webpack lanes).",
  },
  esriArcgisRestJs: {
    label: "`@esri/arcgis-rest-js`",
    source: "https://developers.arcgis.com/arcgis-rest-js/",
    retrieved: "2026-07-13",
    note: "Esri's lightweight REST client family. Small per-package footprint; speaks ArcGIS services only, no map runtime.",
  },
  openlayers: {
    label: "OpenLayers (`ol`)",
    source: "https://openlayers.org/",
    retrieved: "2026-07-13",
    note: "A full renderer + formats library, not a typed multi-protocol service client; size depends heavily on tree-shaken imports.",
  },
};

// ---------------------------------------------------------------------------
// Bundle-size input parsing (docs/bundle-sizes.md is itself generated; this
// script only projects it).
// ---------------------------------------------------------------------------

export function parseBundleSizes(markdown) {
  const generatedLine = markdown.match(/_Generated (\d{4}-\d{2}-\d{2}) at commit `([0-9a-f]+)`\._/);
  if (!generatedLine) throw new Error("docs/bundle-sizes.md: missing generated date/commit line");
  const rows = new Map();
  for (const line of markdown.split(/\r?\n/)) {
    const match = /^\|\s*(.+?)\s*\|\s*([\d.]+ KiB)\s*\|\s*[\d.]+ KiB\s*\|\s*([\d.]+ KiB)\s*\|\s*[\d.]+ KiB\s*\|$/.exec(
      line,
    );
    if (match) rows.set(match[1], { min: match[2], gzip: match[3] });
  }
  if (rows.size === 0) throw new Error("docs/bundle-sizes.md: no measurement rows parsed");
  return { date: generatedLine[1], commit: generatedLine[2], rows };
}

function bundleRow(bundle, label, description) {
  const row = bundle.rows.get(label);
  if (!row) {
    throw new Error(
      `docs/bundle-sizes.md: expected row "${label}" not found — regenerate with npm run report:bundle-sizes or update scripts/generate-comparison-page.mjs`,
    );
  }
  return { label, description, min: row.min, gzip: row.gzip };
}

export function measureMapLibre(rootDir = ROOT) {
  const manifest = JSON.parse(fs.readFileSync(path.join(rootDir, "node_modules", "maplibre-gl", "package.json"), "utf8"));
  const dist = fs.readFileSync(path.join(rootDir, "node_modules", "maplibre-gl", "dist", "maplibre-gl.js"));
  const kib = (bytes) => `${(bytes / 1024).toFixed(1)} KiB`;
  return {
    version: manifest.version,
    min: kib(dist.byteLength),
    gzip: kib(gzipSync(dist, { level: 9 }).byteLength),
  };
}

// ---------------------------------------------------------------------------
// Protocol matrix input parsing. Honua's column in the comparison matrix is
// DERIVED from docs/protocol-capability-matrix.md: each comparison lane names
// the matrix anchors (table columns or documented adapters) that must exist,
// so a protocol cannot appear here without being real in the capability matrix.
// ---------------------------------------------------------------------------

export function parseMatrixProtocolColumns(markdown) {
  for (const line of markdown.split(/\r?\n/)) {
    if (line.startsWith("| Capability |")) {
      return line
        .split("|")
        .map((cell) => cell.trim())
        .filter((cell) => cell.length > 0)
        .slice(1);
    }
  }
  throw new Error("docs/protocol-capability-matrix.md: capability table header not found");
}

