const PROTOCOL_FOOTNOTES = [
  "Notes:",
  "",
  "- (a) OpenLayers ships an `EsriJSON` format; service discovery, paging, auth, and edits are hand-rolled requests.",
  "- (b) Raw MapLibre renders XYZ/raster endpoints you template by hand; there is no capabilities negotiation, feature query, or typed error surface.",
  "- (c) Point a MapLibre GeoJSON source at an `items` URL; paging, filters, CRS negotiation, and edits are yours to build.",
  "- (d) OpenLayers parses GeoJSON and has OGC API tile sources, but has no OGC API Features items client (paging, filters, transactions).",
  "- (e) Via the third-party `ol-stac` package, not OpenLayers itself.",
  "- (f) OpenLayers ships `ol/format/WFS` (GML parsing, filter builders); request orchestration, paging, and transaction bookkeeping are manual.",
  "- (g) Via the official `pmtiles` JS package: install it and call `maplibregl.addProtocol` yourself. Honua auto-registers the protocol on map attach.",
  "- (h) Via the third-party `ol-pmtiles` package.",
  "- (i) Via the `maplibre-gl-geocoder` control plugin, which needs a geocoding API adapter you supply.",
  "- (j) `@esri/arcgis-rest-geocoding` / `-routing` speak Esri's ArcGIS location services only (token/credit metering applies); Honua's providers are pluggable across open services.",
];

function deriveProtocolMatrix(matrixMarkdown, bundle) {
  const columns = parseMatrixProtocolColumns(matrixMarkdown);
  for (const lane of PROTOCOL_LANES) {
    for (const column of lane.matrixColumns ?? []) {
      if (!columns.includes(column)) {
        throw new Error(
          `protocol-capability-matrix.md no longer has column "${column}" (lane "${lane.lane}") — update scripts/generate-comparison-page.mjs`,
        );
      }
    }
    if (lane.matrixText && !matrixMarkdown.includes(lane.matrixText)) {
      throw new Error(
        `protocol-capability-matrix.md no longer documents "${lane.matrixText}" (lane "${lane.lane}") — update scripts/generate-comparison-page.mjs`,
      );
    }
    if (lane.bundleLabel) {
      const hasLabel = [...bundle.rows.keys()].some((label) => label.startsWith(lane.bundleLabel));
      if (!hasLabel) {
        throw new Error(
          `docs/bundle-sizes.md no longer measures ${lane.bundleLabel} (lane "${lane.lane}") — update scripts/generate-comparison-page.mjs`,
        );
      }
    }
  }
  return PROTOCOL_LANES;
}

// ---------------------------------------------------------------------------
// Time-to-first-map reference figures.
// ---------------------------------------------------------------------------

function loadTtfmReference() {
  if (!fs.existsSync(TTFM_REFERENCE_FILE)) return undefined;
  const evidence = JSON.parse(fs.readFileSync(TTFM_REFERENCE_FILE, "utf8"));
  if (evidence.format !== "honua.sdk.time-to-first-map.v1" || evidence.status !== "passed") {
    throw new Error("docs/data/time-to-first-map.json is invalid — regenerate with npm run bench:ttfm -- --write-reference");
  }
  return evidence;
}

const seconds = (ms) => `${(ms / 1000).toFixed(1)} s`;

const kibValue = (text) => {
  const match = /^([\d.]+) KiB$/.exec(text);
  if (!match) throw new Error(`unparseable KiB value: ${text}`);
  return Number(match[1]);
};

const sumAsMb = (...kibTexts) => `${(kibTexts.reduce((total, text) => total + kibValue(text), 0) / 1024).toFixed(2)} MB`;

// ---------------------------------------------------------------------------
// Page rendering.
// ---------------------------------------------------------------------------

export function renderComparisonPage({ bundle, maplibre, lanes, ttfm }) {
  const honuaRows = [
    bundleRow(bundle, "`.` (root)", "Full root entrypoint: connect → query → explain → mount workflow"),
    bundleRow(bundle, "tree-shake guard (`{ HonuaClient }` only)", "Importing only `HonuaClient` (tree-shake guard)"),
    bundleRow(
      bundle,
      "tree-shake guard (`{ mountSourceToMapLibre }` from `/map`)",
      "Data→map bridge only: `mountSourceToMapLibre` from `/map`",
    ),
    bundleRow(bundle, "`/contract`", "Protocol-neutral contract (`Dataset`/`Source`/`Query`/`Result`)"),
    bundleRow(bundle, "`/esri-compat`", "ArcGIS compatibility layer (drop-in migration surface)"),
    bundleRow(bundle, "`/geocoding`", "Geocoding client"),
    bundleRow(bundle, "`/routing`", "Routing client"),
  ];

  const c = CITATIONS;
  const lines = [];
  const push = (...parts) => lines.push(...parts);

  push(
    "<!-- GENERATED FILE — do not edit by hand. -->",
    "<!-- Regenerate with: npm run docs:comparison -->",
    "<!-- Inputs: docs/bundle-sizes.md, docs/protocol-capability-matrix.md, docs/data/time-to-first-map.json, node_modules/maplibre-gl. -->",
    "<!-- Freshness is enforced by npm run docs:comparison:check. -->",
    "",
    "# How Honua compares",
    "",
    "**MapLibre gives you the map. Honua gives you everything else.** `@honua/sdk-js` is a typed,",
    "protocol-neutral geospatial *service client* and migration toolkit that rides open renderers —",
    "it is **not** a rendering engine, so this page does not compare rendering. It compares the",
    "things Honua actually claims: the bytes you ship, the protocols you get a real client for,",
    "and how fast a new project reaches a working map.",
    "",
    "Three ground rules keep this page honest:",
    "",
    "1. **Every Honua number is generated, never hand-edited.** This whole file is produced by",
    "   `npm run docs:comparison` from committed, regenerable inputs; CI fails when it drifts",
    "   (`npm run docs:comparison:check`). See [Methodology](#methodology-and-freshness).",
    "2. **Every external number carries a source URL and an as-of date.**",
    "3. **Non-goals are stated.** Esri's 3D/SceneView stack and MapLibre's rendering quality are",
    "   not competitions we enter; see the",
    "   [three-lanes strategy](./decisions/market-strategy-2026-three-lanes.md).",
    "",
    "## Bundle size",
    "",
    `Honua per-entrypoint sizes below are projected from the generated`,
    `[\`docs/bundle-sizes.md\`](./bundle-sizes.md) (measured ${bundle.date} at commit \`${bundle.commit}\`;`,
    "esbuild `--bundle --minify`, target `es2020`, runtime peers external — the way a real consumer",
    "builds). CI enforces a byte budget on every entrypoint (`npm run verify:bundle-budgets`).",
    "",
    "| What you import | Minified | Gzip |",
    "| --- | ---: | ---: |",
  );
  for (const row of honuaRows) {
    push(`| ${row.description} | ${row.min} | ${row.gzip} |`);
  }
  push(
    "",
    `For context, the rendering engine itself — \`maplibre-gl\` ${maplibre.version}, measured locally from`,
    `this repo's pinned dependency (\`dist/maplibre-gl.js\`) — is ${maplibre.min} minified / **${maplibre.gzip} gzip**.`,
    "A complete Honua + MapLibre app therefore ships roughly the engine plus whichever Honua",
    "entrypoints it imports.",
    "",
    "### Against the alternatives",
    "",
    `**${c.arcgisCore.label}.** ${c.arcgisCore.note} As of ${c.arcgisCore.asOf}:`,
    `the main bundle alone is ${c.arcgisCore.mainBundleMin} minified (${c.arcgisCore.mainBundleGzip} gzip), a`,
    `simple map view loads **${c.arcgisCore.totalJsTransferred} of JavaScript** at startup, and the`,
    `on-disk build output is ${c.arcgisCore.buildOutput}. Source (pinned, retrieved ${c.arcgisCore.retrieved}):`,
    `<${c.arcgisCore.source}>.`,
    "",
    "To be fair in both directions: `@arcgis/core` bundles its own renderer, so the honest",
    "apples-to-apples is *Honua + MapLibre* against `@arcgis/core`. Compared conservatively —",
    `our **uncompressed minified** bytes (engine ${maplibre.min} + Honua root ${honuaRows[0].min} ≈`,
    `${sumAsMb(maplibre.min, honuaRows[0].min)}) against Esri's reported startup JavaScript total`,
    `(${c.arcgisCore.totalJsTransferred}) — the open stack ships roughly a third of the JavaScript, and`,
    `${sumAsMb(maplibre.gzip, honuaRows[0].gzip)} over the wire with gzip. Esri's totals also grow with widgets;`,
    "these figures are its *minimal* samples.",
    "",
    `**${c.esriArcgisRestJs.label}** (<${c.esriArcgisRestJs.source}>, retrieved ${c.esriArcgisRestJs.retrieved}).`,
    `${c.esriArcgisRestJs.note} If all you need is small requests against ArcGIS-only services, it is a`,
    "fine, lighter choice — the comparison that matters is protocol coverage (below), not bytes.",
    "",
    `**${c.openlayers.label}** (<${c.openlayers.source}>, retrieved ${c.openlayers.retrieved}). ${c.openlayers.note}`,
    "",
    "## Protocol coverage",
    "",
    "What you get a first-party, *typed* client for — versus what you hand-roll. Honua's column is",
    "derived from the maintained",
    "[protocol × capability matrix](./protocol-capability-matrix.md) (per-operation detail lives",
    "there; capability misses throw `HonuaCapabilityNotSupportedError` instead of returning empty",
    "results). Competitor columns are deliberately coarse: ✓ first-party support, ◐ partial or",
    "manual assembly, — not provided.",
    "",
    "| Protocol lane | Honua SDK | raw `maplibre-gl` | `@esri/arcgis-rest-js` | OpenLayers |",
    "| --- | --- | --- | --- | --- |",
  );
  for (const lane of lanes) {
    push(`| ${lane.lane} | ${lane.honua} | ${lane.maplibre} | ${lane.arcgisRest} | ${lane.openlayers} |`);
  }
  push("", ...PROTOCOL_FOOTNOTES, "");

  push("## Time to first map", "");
  if (ttfm) {
    const laneLabel =
      ttfm.lane === "browser-first-map"
        ? "rendered-map-ready in headless Chromium (all five quickstart journey stages complete and a MapLibre canvas mounted)"
        : "fixture-server ready + first successful feature query against the mock (no browser rendering measured)";
    push(
      "One scripted, reproducible measurement — from *nothing installed* to a working map against",
      "the deterministic fixture lane (mock GeoServices server; **no live endpoints**):",
      "",
      "| Phase | What is measured | Time |",
      "| --- | --- | ---: |",
      `| Cold install | \`npm install ${ttfm.install.package}\` (v${ttfm.install.version}) into a fresh temp project with an empty npm cache | ${seconds(ttfm.phases.installMs)} |`,
      `| First map | ${laneLabel} | ${seconds(ttfm.phases.firstMapMs)} |`,
      `| **Total** | | **${seconds(ttfm.phases.totalMs)}** |`,
      "",
      `Reference run: ${ttfm.measuredAt}, Node ${ttfm.environment.node}, ${ttfm.environment.platform}/${ttfm.environment.arch},`,
      `${ttfm.environment.cpus} logical CPUs, lane \`${ttfm.lane}\`. Exact definition of the measured signal:`,
      "",
      `> ${ttfm.definition}`,
      "",
    );
  } else {
    push(
      "No committed reference measurement yet. Produce one with the reproducible script below;",
      "`npm run bench:ttfm -- --write-reference` records it and `npm run docs:comparison` projects",
      "it here.",
      "",
    );
  }
  push(
    "Reproduce on your machine from a clean checkout:",
    "",
    "```bash",
    "npm ci",
    "npm run bench:ttfm            # prints install / first-map / total; evidence JSON in test-results/",
    "```",
    "",
    "**Caveats, stated plainly.** The figure is machine-, network-, and registry-dependent — treat",
    "it as a reference point and rerun it locally, not as a guarantee. The mock lane deliberately",
    "excludes live-service latency (that is the point: it measures the SDK + toolchain path, not",
    "someone's server). When Chromium is unavailable the script falls back to the",
    "`node-first-query` lane and the evidence says exactly that — install + fixture-server ready +",
    "first successful query, with no browser rendering claimed.",
    "",
    "## Methodology and freshness",
    "",
    "Every number on this page is regenerable from a clean checkout with one command:",
    "",
    "| Figure | Regenerate with |",
    "| --- | --- |",
    "| Honua per-entrypoint sizes | `npm run report:bundle-sizes` (budgets enforced in CI by `npm run verify:bundle-budgets`) |",
    "| `maplibre-gl` engine size | measured from the pinned `node_modules/maplibre-gl` during `npm run docs:comparison` |",
    "| Protocol lanes (Honua column) | derived from [`docs/protocol-capability-matrix.md`](./protocol-capability-matrix.md) during `npm run docs:comparison` |",
    "| Time to first map | `npm run bench:ttfm -- --write-reference` |",
    "| This page | `npm run docs:comparison` |",
    "",
    "This file is **generated** (`scripts/generate-comparison-page.mjs`) and CI fails when it is",
    "hand-edited or stale (`npm run docs:comparison:check`), mirroring the README's",
    "generated-bundle-table discipline. External figures are cited claims with pinned source URLs",
    "and retrieval dates in the generator source — update them there, with a new date, or not at",
    "all.",
    "",
    "## Try it",
    "",
    "- [60-second quickstart](../README.md#60-second-quickstart) — public endpoint in, typed features out.",
    "- [`standalone-quickstart`](./standalone-quickstart.md) — the CI-kept-green, server-optional example: any public GeoServices endpoint → styled MapLibre map.",
    "- [Demo gallery](https://honua-io.github.io/honua-sdk-js/gallery.html) — all runnable examples.",
    "",
  );
  return `${lines.join("\n").replace(/\n+$/, "")}\n`;
}

export function buildPage(rootDir = ROOT) {
  const bundle = parseBundleSizes(fs.readFileSync(BUNDLE_SIZES_FILE, "utf8"));
  const matrixMarkdown = fs.readFileSync(CAPABILITY_MATRIX_FILE, "utf8");
  const maplibre = measureMapLibre(rootDir);
  const lanes = deriveProtocolMatrix(matrixMarkdown, bundle);
  const ttfm = loadTtfmReference();
  return renderComparisonPage({ bundle, maplibre, lanes, ttfm });
}

function main() {
  const mode = process.argv[2];
  if (mode !== "write" && mode !== "check") {
    process.stderr.write("usage: generate-comparison-page.mjs <write|check>\n");
    process.exit(2);
  }
  const content = buildPage();
  if (mode === "write") {
    fs.writeFileSync(OUTPUT_FILE, content, "utf8");
    process.stdout.write(`wrote ${path.relative(ROOT, OUTPUT_FILE)} (${content.length} bytes)\n`);
    return;
  }
  // Normalize CRLF so a core.autocrlf checkout on Windows still compares clean.
  const existing = (fs.existsSync(OUTPUT_FILE) ? fs.readFileSync(OUTPUT_FILE, "utf8") : "").replace(/\r\n/g, "\n");
  if (existing !== content) {
    process.stderr.write("drift: docs/comparison.md is out of date; run `npm run docs:comparison`\n");
    process.exit(1);
  }
  process.stdout.write("docs/comparison.md is up to date\n");
}

const invokedDirectly = process.argv[1] && pathToFileURL(process.argv[1]).href === import.meta.url;
if (invokedDirectly) main();
